class_name DialogueRunnerNode
extends Node

@export var dialogue_lines: Array[Dictionary] = []

var current_index: int = 0


func get_current_line() -> Dictionary:
	if current_index >= 0 and current_index < dialogue_lines.size():
		return dialogue_lines[current_index]
	return {}


func advance() -> bool:
	current_index += 1
	return current_index >= 0 and current_index < dialogue_lines.size()
